import os
import numpy as np


def eval():
    pred_traj_path = "pred_results/pred_md.traj"
    pred_summary_path = "pred_results/pred_rotate_summary.txt"

    # Step 1: File existence checks
    for path, label in [
        (pred_traj_path, "predicted trajectory"),
        (pred_summary_path, "predicted summary"),
    ]:
        if not os.path.exists(path):
            return (False, f"Missing {label} file: {path}")

    # Load trajectory
    try:
        from ase.io.trajectory import Trajectory

        pred_traj = Trajectory(pred_traj_path)
    except Exception as e:
        return (False, f"Failed to load trajectory files: {e}")

    # Step 2: Frame count - accept 50 or 51 frames (50 steps can mean 50 or 51 frames)
    n_frames = len(pred_traj)
    if n_frames not in [50, 51]:
        return (
            False,
            f"Frame count should be 50 or 51 (for 50 steps), got {n_frames}",
        )

    # Check that we have atoms
    if n_frames == 0:
        return (False, "Trajectory is empty")

    n_atoms = len(pred_traj[0])
    if n_atoms == 0:
        return (False, "No atoms in trajectory frames")

    # Step 3: Check for NaN or Inf in all frames
    for i in range(n_frames):
        pred_pos = pred_traj[i].get_positions()
        if not np.all(np.isfinite(pred_pos)):
            return (False, f"Frame {i} contains NaN or Inf values in predicted positions")

    # Step 4: Verify rotation center (atom 1) stays fixed throughout trajectory
    original_pos = pred_traj[0].get_positions()
    center_atom = 1
    max_center_disp = 0.0
    for i in range(n_frames):
        pred_pos = pred_traj[i].get_positions()
        disp = np.linalg.norm(pred_pos[center_atom] - original_pos[center_atom])
        max_center_disp = max(max_center_disp, disp)

    if max_center_disp > 1e-6:
        return (
            False,
            f"Rotation center (atom 1) displaced by {max_center_disp:.6e} A (threshold: 1e-6)",
        )

    # Step 5: Verify rigid body rotation (distance preservation)
    try:
        from scipy.spatial.distance import pdist
        original_distances = pdist(original_pos)
        max_dist_rmsd = 0.0
        for i in range(n_frames):
            pred_pos = pred_traj[i].get_positions()
            frame_distances = pdist(pred_pos)
            rmsd = np.sqrt(np.mean((frame_distances - original_distances) ** 2))
            max_dist_rmsd = max(max_dist_rmsd, rmsd)

        if max_dist_rmsd > 1e-4:
            return (
                False,
                f"Rigid body violation: distance RMSD {max_dist_rmsd:.6e} A exceeds threshold 1e-4",
            )
    except ImportError:
        # If scipy not available, do manual distance check
        max_dist_rmsd = 0.0
        for i in range(n_frames):
            pred_pos = pred_traj[i].get_positions()
            # Check a subset of pairwise distances
            for a in range(min(n_atoms, 5)):
                for b in range(a+1, min(n_atoms, 5)):
                    d_orig = np.linalg.norm(original_pos[a] - original_pos[b])
                    d_frame = np.linalg.norm(pred_pos[a] - pred_pos[b])
                    max_dist_rmsd = max(max_dist_rmsd, abs(d_orig - d_frame))
        if max_dist_rmsd > 1e-4:
            return (False, f"Rigid body violation: max distance change {max_dist_rmsd:.6e} A")

    # Step 6: Verify that rotation actually occurs (positions change)
    first_pos = pred_traj[0].get_positions()
    last_pos = pred_traj[-1].get_positions()
    max_displacement = np.max(np.abs(last_pos - first_pos))

    # If all positions are the same across all frames, something is wrong
    # (unless rotation angle is 0 or multiple of 360, but we expect meaningful rotation)
    all_same = True
    for i in range(1, n_frames):
        pos_i = pred_traj[i].get_positions()
        if np.max(np.abs(pos_i - first_pos)) > 1e-6:
            all_same = False
            break

    if all_same:
        return (False, "All frames have identical positions - no rotation occurred")

    # Step 7: Verify rotation uses axis defined by atoms 0 and 1
    # The rotation axis should be along the direction from atom 1 to atom 0
    # Check that atom 0 moves along a circular arc around atom 1
    pos_center = first_pos[center_atom]
    pos_atom0_initial = first_pos[0]

    # Vector from center to atom 0
    r_vec = pos_atom0_initial - pos_center
    r_mag = np.linalg.norm(r_vec)

    if r_mag > 1e-10:
        # All frames should have atom 0 at the same distance from center
        for i in range(n_frames):
            pred_pos = pred_traj[i].get_positions()
            r_vec_i = pred_pos[0] - pos_center
            r_mag_i = np.linalg.norm(r_vec_i)
            if abs(r_mag_i - r_mag) > 1e-4:
                return (
                    False,
                    f"Frame {i}: atom 0 distance from rotation center changed "
                    f"from {r_mag:.6f} to {r_mag_i:.6f} A",
                )

    # Step 8: Verify the rotation is progressive (angles should be monotonically increasing or consistent)
    # Check that consecutive frames show consistent angular steps
    if n_frames >= 3 and r_mag > 1e-10:
        # Compute rotation axis
        axis = r_vec / r_mag

        # Compute angles between consecutive frames for atom 0
        angles = []
        for i in range(1, min(n_frames, 10)):  # Check first 10 frames
            pred_pos_prev = pred_traj[i-1].get_positions()
            pred_pos_curr = pred_traj[i].get_positions()

            v1 = pred_pos_prev[0] - pos_center
            v2 = pred_pos_curr[0] - pos_center

            # Normalize
            v1_mag = np.linalg.norm(v1)
            v2_mag = np.linalg.norm(v2)

            if v1_mag > 1e-10 and v2_mag > 1e-10:
                cos_angle = np.clip(np.dot(v1, v2) / (v1_mag * v2_mag), -1.0, 1.0)
                angle = np.arccos(cos_angle)
                angles.append(np.degrees(angle))

        if len(angles) >= 2:
            # Check that angular steps are roughly consistent (within 10x of each other)
            angle_std = np.std(angles)
            angle_mean = np.mean(angles)
            if angle_mean > 1e-6 and angle_std / angle_mean > 0.5:
                return (
                    False,
                    f"Non-uniform angular steps detected: mean={angle_mean:.4f}°, "
                    f"std={angle_std:.4f}°",
                )

    # Step 9: Summary report validation
    try:
        with open(pred_summary_path, "r") as f:
            pred_summary = f.read().lower()
    except Exception as e:
        return (False, f"Failed to read predicted summary: {e}")

    # Check required content in summary - be lenient
    required_keywords = ["rotation", "axis", "angle"]
    missing = [kw for kw in required_keywords if kw not in pred_summary]
    if len(missing) > 1:
        return (
            False,
            f"Summary report missing required keywords: {missing}",
        )

    return (
        True,
        f"All checks passed. Frames: {n_frames}, "
        f"center displacement: {max_center_disp:.6e} A, "
        f"max distance RMSD: {max_dist_rmsd:.6e} A",
    )


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

import os
import re
import math
import subprocess
import sys


def get_output_text():
    """Try to get output from various sources."""
    output_text = None

    # Check for stdout capture
    for stdout_file in ["pred_results/stdout.txt", "stdout.txt", "pred_results/output.txt"]:
        if os.path.exists(stdout_file):
            with open(stdout_file, 'r') as f:
                content = f.read()
                if content.strip():
                    return content

    # Check for any output files in pred_results
    pred_dir = "pred_results"
    if os.path.exists(pred_dir):
        for f in os.listdir(pred_dir):
            fpath = os.path.join(pred_dir, f)
            if os.path.isfile(fpath) and not f.endswith('.py'):
                try:
                    with open(fpath, 'r') as fp:
                        content = fp.read()
                        if content.strip():
                            output_text = (output_text or "") + "\n" + content
                except Exception:
                    pass

    if output_text and output_text.strip():
        return output_text

    # Try running any solution Python files
    solution_files = []
    for root, dirs, files in os.walk('.'):
        dirs[:] = [d for d in dirs if not d.startswith('.') 
                   and d not in ['benchmark', '__pycache__', 'node_modules']]
        for f in files:
            if f.endswith('.py') and f not in ['eval.py', 'evaluate.py']:
                solution_files.append(os.path.join(root, f))

    for sol_file in solution_files:
        try:
            result = subprocess.run(
                [sys.executable, sol_file],
                capture_output=True,
                text=True,
                timeout=60,
                cwd='.'
            )
            combined = result.stdout + result.stderr
            if combined.strip():
                return combined
        except Exception:
            pass

    return output_text or ""


def check_solution_code():
    """Check if the solution code has the required components."""
    solution_files = []

    # Look in pred_results first
    for root, dirs, files in os.walk('pred_results'):
        for f in files:
            if f.endswith('.py'):
                solution_files.append(os.path.join(root, f))

    # Then look elsewhere
    if not solution_files:
        for root, dirs, files in os.walk('.'):
            dirs[:] = [d for d in dirs if not d.startswith('.') 
                       and d not in ['benchmark', '__pycache__']]
            for f in files:
                if f.endswith('.py') and f not in ['eval.py', 'evaluate.py']:
                    solution_files.append(os.path.join(root, f))

    for sol_file in solution_files:
        try:
            with open(sol_file, 'r') as f:
                code = f.read()

            checks = {
                'json_loading': bool(re.search(r'json\s*\.\s*load|json\.loads', code)),
                'file_path': bool(re.search(r'ffield\.json|I-ReaxFF', code)),
                'atom_parsing': bool(re.search(r'atom|mass', code, re.IGNORECASE)),
                'bond_parsing': bool(re.search(r'bond|rEquilibrium|Depi', code, re.IGNORECASE)),
                'validation': bool(re.search(r'warning|Warning|warn|valid', code, re.IGNORECASE)),
                'energy_calc': bool(re.search(r'energy|Energy', code, re.IGNORECASE)),
                'output': bool(re.search(r'print\s*\(', code)),
            }

            return checks, code
        except Exception:
            pass

    return {}, ""


def eval():
    """
    Evaluate the solution for ReaxFF force field parameter loading and validation.

    Checks:
    1. Force field parameters are loaded (atom types, bond types, etc.)
    2. Validation is performed with warnings for issues found
    3. Energy calculations are demonstrated
    4. Numerical values are reasonable
    """

    output_text = get_output_text()
    code_checks, code = check_solution_code()

    reasons_pass = []
    reasons_fail = []

    # =========================================================
    # PRIMARY: Check output content
    # =========================================================

    if output_text and output_text.strip():

        # Check 1: Parameter loading information
        # Look for any indication that parameters were loaded
        param_loading_patterns = [
            r'\d+\s*(?:unique\s*)?atom\s*type',
            r'atom\s*type[s]?\s*[:\-]\s*\d+',
            r'[Ll]oaded\s+\d+',
            r'[Ff]ound\s+\d+',
            r'atom\s*type[s]?.*?C\b',  # mentions C atom type
            r'\bC\b.*atom',
            r'bond\s*type',
            r'rEquilibrium',
            r'C-C|C-H|H-H',  # bond type names
        ]

        has_param_loading = any(re.search(p, output_text, re.IGNORECASE) 
                                for p in param_loading_patterns)

        if has_param_loading:
            reasons_pass.append("Parameter loading information present")
        else:
            reasons_fail.append("No parameter loading information found")

        # Check 2: Validation warnings or results
        validation_patterns = [
            r'[Ww]arning',
            r'[Vv]alidat',
            r'[Mm]issing\s+(?:Depi|parameter|bond)',
            r'[Nn]egative',
            r'[Oo]utside.*range',
            r'[Ii]ssue',
            r'[Nn]o\s+(?:angle|torsion)\s+parameters',
            r'[Bb]ond.*[Vv]alidat',
        ]

        has_validation = any(re.search(p, output_text, re.IGNORECASE) 
                             for p in validation_patterns)

        if has_validation:
            reasons_pass.append("Validation results/warnings present")
        else:
            reasons_fail.append("No validation results or warnings found")

        # Check 3: Energy calculation
        energy_patterns = [
            r'[Ee]nergy',
            r'[Ee]V\b',
            r'kcal',
            r'kJ',
        ]

        has_energy = any(re.search(p, output_text) for p in energy_patterns)

        if has_energy:
            reasons_pass.append("Energy calculation present")
        else:
            reasons_fail.append("No energy calculation found")

        # Check 4: Numerical values present
        numerical_values = re.findall(r'[-+]?\d+\.\d+', output_text)
        has_numerical = len(numerical_values) > 0

        if has_numerical:
            # Verify values are finite
            all_finite = True
            for val_str in numerical_values[:20]:
                try:
                    val = float(val_str)
                    if math.isnan(val) or math.isinf(val):
                        all_finite = False
                        break
                except ValueError:
                    pass

            if all_finite:
                reasons_pass.append(f"Numerical values present and finite ({len(numerical_values)} found)")
            else:
                reasons_fail.append("Non-finite numerical values found")
        else:
            reasons_fail.append("No numerical values in output")

        # Check 5: Bond energy calculation specifically
        bond_energy_patterns = [
            r'[Bb]ond.*[Ee]nergy',
            r'[Ee]nergy.*bond',
            r'[Cc]alculated.*energy',
            r'energy.*=.*[-+]?\d',
            r'[Ee]quilibrium.*length',
            r'r0|re\b',
        ]

        has_bond_energy = any(re.search(p, output_text, re.IGNORECASE) 
                              for p in bond_energy_patterns)

        if has_bond_energy:
            reasons_pass.append("Bond energy calculation with details present")
        else:
            # Not strictly required but good to have
            pass

        # Check 6: C-C bond (known to be in the dataset)
        has_cc = bool(re.search(r'C-C|CC\b', output_text))
        if has_cc:
            reasons_pass.append("C-C bond parameters referenced")

        # Check 7: Warnings about specific known issues
        # The dataset has bonds C-H, H-C, H-H, others with missing Depi
        has_specific_warnings = bool(re.search(
            r'C-H|H-C|H-H|[Mm]issing|Depi|[Oo]thers',
            output_text
        ))
        if has_specific_warnings:
            reasons_pass.append("Specific parameter issues identified")

        # Scoring
        core_checks = [
            has_param_loading,
            has_validation,
            has_energy,
            has_numerical,
        ]

        core_score = sum(core_checks)

        if core_score >= 3:
            msg = f"PASSED: {core_score}/4 core checks passed. "
            msg += "Passed: " + "; ".join(reasons_pass)
            if reasons_fail:
                msg += ". Minor issues: " + "; ".join(reasons_fail)
            return (True, msg)
        elif core_score >= 2:
            # Check if code quality makes up for it
            code_quality = sum(1 for v in code_checks.values() if v)
            if code_quality >= 5:
                msg = f"PASSED: Output score {core_score}/4 but code quality is good ({code_quality}/7 code checks). "
                msg += "Passed: " + "; ".join(reasons_pass)
                return (True, msg)
            else:
                msg = f"FAILED: Only {core_score}/4 core checks passed. "
                msg += "Failed: " + "; ".join(reasons_fail)
                return (False, msg)
        else:
            msg = f"FAILED: Only {core_score}/4 core checks passed. "
            msg += "Failed: " + "; ".join(reasons_fail)
            if reasons_pass:
                msg += ". Passed: " + "; ".join(reasons_pass)
            return (False, msg)

    # =========================================================
    # SECONDARY: Check code quality if no output available
    # =========================================================

    if code_checks:
        required_checks = ['json_loading', 'file_path', 'validation', 'energy_calc', 'output']
        passed_required = [c for c in required_checks if code_checks.get(c, False)]
        failed_required = [c for c in required_checks if not code_checks.get(c, False)]

        if len(passed_required) >= 4:
            return (True, f"Output not captured but solution code contains all required components: {', '.join(passed_required)}")
        elif len(passed_required) >= 3:
            return (True, f"Output not captured but solution code contains most required components: {', '.join(passed_required)}. Missing: {', '.join(failed_required)}")
        else:
            return (False, f"Output not captured and solution code missing required components. Has: {', '.join(passed_required)}. Missing: {', '.join(failed_required)}")

    return (False, "No output captured and no solution code found to evaluate")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

import json
import os
import numpy as np


def eval():
    pred_dir = "pred_results"

    pred_analysis_path = os.path.join(pred_dir, "pred_gp_uncertainty_analysis.json")
    pred_params_path = os.path.join(pred_dir, "pred_gp_uncertainty.json")

    # Step 1: Verify output files exist
    if not os.path.exists(pred_analysis_path):
        return (False, f"Missing file: {pred_analysis_path}")
    if not os.path.exists(pred_params_path):
        return (False, f"Missing file: {pred_params_path}")

    # Step 2: Verify files are valid JSON
    try:
        with open(pred_analysis_path) as f:
            pred_analysis = json.load(f)
    except json.JSONDecodeError as e:
        return (False, f"Invalid JSON in analysis file: {e}")

    try:
        with open(pred_params_path) as f:
            pred_params = json.load(f)
    except json.JSONDecodeError as e:
        return (False, f"Invalid JSON in params file: {e}")

    # Step 3: Check that analysis file has meaningful content
    if not isinstance(pred_analysis, dict) or len(pred_analysis) == 0:
        return (False, "Analysis file is empty or not a dictionary")

    if not isinstance(pred_params, dict) or len(pred_params) == 0:
        return (False, "Params file is empty or not a dictionary")

    # Step 4: Check for GP-related content in analysis file
    # Accept various naming conventions
    analysis_str = json.dumps(pred_analysis).lower()

    # Check for uncertainty/std information
    has_uncertainty = any(key in analysis_str for key in [
        'std', 'uncertainty', 'prediction_std', 'uncertainties'
    ])
    if not has_uncertainty:
        return (False, "Analysis file missing uncertainty/std information from GP predictions")

    # Check for score/performance metric
    has_score = any(key in analysis_str for key in [
        'score', 'rmse', 'r2', 'mse', 'error', 'accuracy'
    ])
    if not has_score:
        return (False, "Analysis file missing GP performance score/metric")

    # Check for bond statistics
    has_bond_stats = any(key in analysis_str for key in [
        'bond', 'length', 'distance', 'statistics', 'mean', 'std'
    ])
    if not has_bond_stats:
        return (False, "Analysis file missing bond statistics")

    # Step 5: Validate numerical values are reasonable
    def find_values_by_key_fragment(d, fragments, visited=None):
        """Recursively find all numeric values whose keys contain any fragment."""
        if visited is None:
            visited = set()
        results = {}
        if id(d) in visited:
            return results
        visited.add(id(d))

        if isinstance(d, dict):
            for k, v in d.items():
                k_lower = str(k).lower()
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    for frag in fragments:
                        if frag in k_lower:
                            results[k] = v
                elif isinstance(v, (dict, list)):
                    results.update(find_values_by_key_fragment(v, fragments, visited))
        elif isinstance(d, list):
            for item in d:
                if isinstance(item, (dict, list)):
                    results.update(find_values_by_key_fragment(item, fragments, visited))
        return results

    # Check uncertainty values are non-negative
    std_values = find_values_by_key_fragment(pred_analysis, ['std', 'uncertainty'])
    for key, val in std_values.items():
        if isinstance(val, (int, float)) and val < 0:
            return (False, f"Negative uncertainty value found: {key}={val}")

    # Step 6: Check params file has GP-related content
    params_str = json.dumps(pred_params).lower()
    has_kernel = any(key in params_str for key in [
        'kernel', 'rbf', 'length_scale', 'constant', 'gp', 'gaussian'
    ])
    has_training = any(key in params_str for key in [
        'training', 'train', 'data', 'lengths', 'orders', 'n_restarts', 'optimizer'
    ])

    if not has_kernel and not has_training:
        return (False, "Params file missing GP kernel or training information")

    # Step 7: Check that prediction uncertainties exist and are a list/array
    # Accept various key names for uncertainties
    uncertainty_data = None
    for key in pred_analysis:
        k_lower = key.lower()
        if any(frag in k_lower for frag in ['uncertainty', 'uncertainties', 'std', 'prediction_std']):
            val = pred_analysis[key]
            if isinstance(val, list):
                uncertainty_data = val
                break
            elif isinstance(val, dict):
                # Could be nested
                for subkey, subval in val.items():
                    if isinstance(subval, list) and len(subval) > 0:
                        uncertainty_data = subval
                        break

    if uncertainty_data is not None:
        # Validate the uncertainty values
        try:
            uncertainty_arr = np.array(uncertainty_data, dtype=float)
            if len(uncertainty_arr) == 0:
                return (False, "Prediction uncertainties list is empty")
            if np.any(uncertainty_arr < 0):
                return (False, "Some prediction uncertainties are negative")
            # Uncertainties should be finite
            if not np.all(np.isfinite(uncertainty_arr)):
                return (False, "Some prediction uncertainties are not finite (NaN or Inf)")
        except (ValueError, TypeError) as e:
            # If it's nested, that's okay - just check it exists
            pass

    # Step 8: Check bond statistics have reasonable values
    # Look for mean bond length values (C-H bonds are typically 1.0-1.2 Angstroms)
    def find_all_numeric_values(d, visited=None):
        """Recursively find all numeric values."""
        if visited is None:
            visited = set()
        values = []
        if id(d) in visited:
            return values
        visited.add(id(d))

        if isinstance(d, dict):
            for k, v in d.items():
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    values.append((k, v))
                elif isinstance(v, (dict, list)):
                    values.extend(find_all_numeric_values(v, visited))
        elif isinstance(d, list):
            for item in d:
                if isinstance(item, (dict, list)):
                    values.extend(find_all_numeric_values(item, visited))
        return values

    # Check for RMSE - if present, should be reasonable for bond order prediction
    rmse_values = find_values_by_key_fragment(pred_analysis, ['rmse'])
    for key, val in rmse_values.items():
        if isinstance(val, (int, float)):
            if val < 0:
                return (False, f"Negative RMSE value: {key}={val}")
            if val > 10:
                return (False, f"Unreasonably large RMSE value: {key}={val} (expected < 10 for bond orders)")

    # Check R² scores if present - should be between -1 and 1 (or at least not absurdly large)
    r2_values = find_values_by_key_fragment(pred_analysis, ['r2', 'score', 'r_squared'])
    for key, val in r2_values.items():
        if isinstance(val, (int, float)):
            if val > 1.01:  # Allow tiny floating point errors
                return (False, f"R² score {key}={val} is greater than 1.0, which is invalid")

    # Step 9: Verify the analysis file structure has the key components mentioned in the task
    # The task requires: GP scores, prediction uncertainties, bond statistics
    has_gp_scores = False
    has_pred_uncertainties = False
    has_bond_stats = False

    for key in pred_analysis:
        k_lower = key.lower()
        if any(frag in k_lower for frag in ['score', 'gp_score', 'gaussian']):
            has_gp_scores = True
        if any(frag in k_lower for frag in ['uncertainty', 'uncertainties', 'prediction']):
            has_pred_uncertainties = True
        if any(frag in k_lower for frag in ['bond', 'statistic', 'stat']):
            has_bond_stats = True

    # Also check nested structure
    if not has_gp_scores:
        # Check if scores are nested within other keys
        for key, val in pred_analysis.items():
            if isinstance(val, dict):
                for subkey in val:
                    sk_lower = subkey.lower()
                    if any(frag in sk_lower for frag in ['score', 'rmse', 'r2', 'error']):
                        has_gp_scores = True
                        break

    if not has_gp_scores:
        return (False, "Analysis file missing GP scores/performance metrics")

    if not has_pred_uncertainties:
        return (False, "Analysis file missing prediction uncertainties")

    if not has_bond_stats:
        return (False, "Analysis file missing bond statistics")

    # Step 10: Verify training data was actually used (check params file)
    # Should have some indication of training data size
    training_data_present = False
    for key in pred_params:
        k_lower = key.lower()
        if any(frag in k_lower for frag in ['training', 'train', 'data', 'kernel', 'n_restart']):
            training_data_present = True
            break

    if not training_data_present:
        return (False, "Params file missing training configuration information")

    return (True, "All checks passed: Output files exist, contain valid JSON with GP scores, "
                  "prediction uncertainties, bond statistics, and training parameters. "
                  "Numerical values are within reasonable ranges.")


