import os
import csv
import numpy as np
from PIL import Image


def eval():
    pred_dir = "pred_results"

    pred_csv = os.path.join(pred_dir, "pred_integrate_C_O.csv")
    pred_png = os.path.join(pred_dir, "pred_integrate_C_O.png")
    pred_txt = os.path.join(pred_dir, "pred_integrate_C_O_summary.txt")

    # Step 1: Verify file existence
    for f, label in [(pred_csv, "CSV"), (pred_png, "PNG"), (pred_txt, "TXT")]:
        if not os.path.exists(f):
            return (False, f"Missing predicted {label} file: {f}")

    # Step 2: Load and validate CSV data
    def load_csv(path):
        with open(path, "r") as f:
            reader = csv.reader(f)
            header = next(reader)
            rows = []
            for row in reader:
                rows.append([float(x) for x in row])
        return header, np.array(rows)

    try:
        pred_header, pred_data = load_csv(pred_csv)
    except Exception as e:
        return (False, f"Error loading CSV file: {e}")

    # Check minimum required columns: distance + vdw + bond_lower + bond_upper + at least one total
    if len(pred_header) < 4:
        return (False, f"Predicted CSV has only {len(pred_header)} columns, expected at least 4 (distance, vdw, bond energies)")

    # Check sufficient data points
    if pred_data.shape[0] < 10:
        return (False, f"Predicted CSV has only {pred_data.shape[0]} rows, expected at least 10")

    # Check for NaN or inf
    if np.any(np.isnan(pred_data)) or np.any(np.isinf(pred_data)):
        return (False, "Predicted CSV contains NaN or infinite values")

    # Step 3: Validate distance range
    pred_distances = pred_data[:, 0]
    if pred_distances.min() > 1.25 or pred_distances.max() < 1.75:
        return (False, f"Distance range [{pred_distances.min():.3f}, {pred_distances.max():.3f}] does not cover expected [1.2, 1.8] range")

    # Step 4: Validate bond energy physics
    r_eq = 1.43
    k_lower = 3.1
    k_upper = 3.0

    # Expected bond energies at equilibrium distance should be ~0
    eq_idx = np.argmin(np.abs(pred_distances - r_eq))

    # Check if any column has near-zero value at equilibrium (characteristic of harmonic potential)
    found_harmonic_lower = False
    found_harmonic_upper = False

    for col_idx in range(1, pred_data.shape[1]):
        col_data = pred_data[:, col_idx]

        # Compute expected harmonic values
        expected_lower = 0.5 * k_lower * (pred_distances - r_eq)**2
        expected_upper = 0.5 * k_upper * (pred_distances - r_eq)**2

        # Check if this column matches harmonic potential for either spring constant
        if np.allclose(col_data, expected_lower, rtol=0.1, atol=0.05):
            found_harmonic_lower = True
        if np.allclose(col_data, expected_upper, rtol=0.1, atol=0.05):
            found_harmonic_upper = True

    if not found_harmonic_lower:
        return (False, f"Could not find a bond energy column matching harmonic potential with k={k_lower}")

    if not found_harmonic_upper:
        return (False, f"Could not find a bond energy column matching harmonic potential with k={k_upper}")

    # Step 5: Validate VdW energy column exists and has reasonable values
    vdw_col_found = False
    for col_idx in range(1, pred_data.shape[1]):
        col_data = pred_data[:, col_idx]
        expected_lower = 0.5 * k_lower * (pred_distances - r_eq)**2
        expected_upper = 0.5 * k_upper * (pred_distances - r_eq)**2

        if (not np.allclose(col_data, expected_lower, rtol=0.1, atol=0.05) and 
            not np.allclose(col_data, expected_upper, rtol=0.1, atol=0.05)):
            vdw_col_found = True
            break

    if not vdw_col_found:
        return (False, "Could not find a VdW energy column (non-harmonic energy component)")

    # Step 6: Check that total energy columns exist
    if pred_data.shape[1] < 4:
        return (False, "CSV should have at least 4 columns including total energy")

    # Step 7: Validate PNG exists and has reasonable size
    try:
        img = Image.open(pred_png)
        w, h = img.size
        if w < 200 or h < 200:
            return (False, f"PNG image is too small: {w}x{h}")
    except Exception as e:
        return (False, f"Error reading PNG file: {e}")

    # Step 8: Validate summary TXT file
    try:
        with open(pred_txt, "r") as f:
            txt_content = f.read().lower()

        # Check that some energy values are reported (flexible check)
        has_energy_info = any(kw in txt_content for kw in [
            "energy", "evdw", "e_vdw", "vdw", "bond", "van der waals"
        ])
        if not has_energy_info:
            return (False, "Summary TXT does not contain energy information")

        # Check that parameters are mentioned - flexible check for key computational parameters
        # The task uses r_eq=1.43, k_lower=3.1, k_upper=3.0
        has_params = any(kw in txt_content for kw in [
            "1.43", "3.1", "3.0", "equilibrium", "spring", "k_lower", "k_upper",
            "k=3.1", "k=3.0", "1.2", "1.8"
        ])
        if not has_params:
            return (False, "Summary TXT does not mention key computational parameters (r_eq, spring constants, or distance range)")

        # Check that some numerical results are present (minimum energy values, distances, etc.)
        # Look for numbers that could be energy values or distances
        import re
        numbers_found = re.findall(r'-?\d+\.\d+', txt_content)
        if len(numbers_found) < 3:
            return (False, "Summary TXT does not contain sufficient numerical results")

    except Exception as e:
        return (False, f"Error reading summary TXT: {e}")

    # Step 9: Validate distance resolution
    if len(pred_distances) < 20:
        return (False, f"Only {len(pred_distances)} distance points, expected at least 20 for adequate resolution")

    return (True, "All evaluation checks passed: files exist, numerical results contain correct energy components, physical constraints satisfied")


