import json
import os
import math
import re

PRED_JSON = 'pred_results/pred_reconstructed_ES_imagenet.json'
PRED_TXT = 'pred_results/pred_reconstructed_ES_imagenet.txt'


def parse_shape(shape_val):
    """Parse shape from various formats (list, tuple, string)."""
    if shape_val is None:
        return None
    if isinstance(shape_val, (list, tuple)):
        return list(shape_val)
    if isinstance(shape_val, str):
        nums = re.findall(r'\d+', shape_val)
        if nums:
            return [int(n) for n in nums]
    return None


def check_shape_valid(shape):
    """Check if a shape is valid for this task: should end with 224x224."""
    if shape is None:
        return False
    if len(shape) >= 2:
        return shape[-1] == 224 and shape[-2] == 224
    return False


def find_shapes_in_data(data):
    """
    Recursively search for shape information in the JSON data.
    Returns list of found shapes.
    """
    shapes = []

    if isinstance(data, list):
        # Could be a list of shapes directly: [[1,224,224], [1,224,224], ...]
        # Check if elements look like shapes (lists of ints)
        if all(isinstance(item, (list, tuple)) and all(isinstance(x, int) for x in item) for item in data if item):
            for item in data:
                s = parse_shape(item)
                if s is not None:
                    shapes.append(s)
        else:
            # Recurse into list elements
            for item in data:
                shapes.extend(find_shapes_in_data(item))

    elif isinstance(data, dict):
        # Look for shape-related keys
        shape_keys = ['shape', 'image_shape', 'tensor_shape', 'output_shape', 
                      'sample_shapes', 'shapes']
        for key in shape_keys:
            if key in data:
                val = data[key]
                if isinstance(val, list):
                    # Could be a single shape [1,224,224] or list of shapes [[1,224,224],...]
                    if len(val) > 0:
                        if isinstance(val[0], (list, tuple)):
                            # List of shapes
                            for s in val:
                                parsed = parse_shape(s)
                                if parsed is not None:
                                    shapes.append(parsed)
                        elif isinstance(val[0], int):
                            # Single shape
                            parsed = parse_shape(val)
                            if parsed is not None:
                                shapes.append(parsed)
                elif isinstance(val, str):
                    parsed = parse_shape(val)
                    if parsed is not None:
                        shapes.append(parsed)

        # Also recurse into values for nested structures
        for key, val in data.items():
            if key not in shape_keys:  # avoid double processing
                if isinstance(val, (dict, list)):
                    shapes.extend(find_shapes_in_data(val))

    return shapes


def find_num_samples(data):
    """Try to find number of samples in the data."""
    if isinstance(data, dict):
        for key in ['num_samples', 'total_samples', 'dataset_size', 'size', 'length', 'n_samples']:
            if key in data and isinstance(data[key], (int, float)):
                return int(data[key])

        # Check nested structures
        for key in ['train', 'val', 'validation', 'test']:
            if key in data and isinstance(data[key], dict):
                result = find_num_samples(data[key])
                if result is not None:
                    return result

        # If it's a list of samples
        for key in ['samples', 'results', 'data']:
            if key in data and isinstance(data[key], list):
                return len(data[key])

    elif isinstance(data, list):
        return len(data)

    return None


def find_labels_in_data(data):
    """Try to find label information in the data."""
    labels = []

    if isinstance(data, dict):
        # Look for label distribution or label list
        for key in ['label_distribution', 'labels', 'class_distribution', 'label_counts']:
            if key in data:
                val = data[key]
                if isinstance(val, dict):
                    # label_distribution: {"0": 5, "1": 3, ...}
                    for k in val.keys():
                        try:
                            labels.append(int(k))
                        except (ValueError, TypeError):
                            pass
                elif isinstance(val, list):
                    labels.extend([v for v in val if isinstance(v, (int, float))])

        # Per-sample label
        for key in ['label', 'class_label', 'class_id', 'target']:
            if key in data and isinstance(data[key], (int, float)):
                labels.append(int(data[key]))

        # Recurse
        for key, val in data.items():
            if isinstance(val, (dict, list)):
                labels.extend(find_labels_in_data(val))

    elif isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                labels.extend(find_labels_in_data(item))

    return labels


def find_preprocessing_info(data):
    """Check if preprocessing pipeline information is present."""
    if isinstance(data, dict):
        for key in ['preprocessing_steps', 'preprocessing', 'pipeline', 'steps', 
                    'processing_steps', 'description']:
            if key in data:
                val = data[key]
                if isinstance(val, (list, str)) and len(val) > 0:
                    return True

        # Recurse
        for val in data.values():
            if isinstance(val, dict):
                if find_preprocessing_info(val):
                    return True

    return False


def eval():
    errors = []
    warnings = []

    # Check that predicted files exist
    if not os.path.exists(PRED_JSON):
        return (False, f"Missing predicted JSON file: {PRED_JSON}")
    if not os.path.exists(PRED_TXT):
        return (False, f"Missing predicted TXT file: {PRED_TXT}")

    # Load predicted JSON
    try:
        with open(PRED_JSON, 'r') as f:
            pred = json.load(f)
    except Exception as e:
        return (False, f"Failed to load predicted JSON: {e}")

    if not isinstance(pred, (dict, list)):
        return (False, "Predicted JSON should be a dict or list at the top level")

    # ---- Check 1: Dataset has samples ----
    num_samples = find_num_samples(pred)
    if num_samples is None:
        # Try to infer from other fields
        if isinstance(pred, list):
            num_samples = len(pred)
        else:
            warnings.append("Could not determine number of samples from JSON")
    else:
        if num_samples <= 0:
            errors.append(f"Number of samples should be positive, got {num_samples}")
        else:
            pass  # Good

    # ---- Check 2: Output shapes are 224x224 ----
    shapes = find_shapes_in_data(pred)

    if len(shapes) == 0:
        # Try to find shape info in string representation
        pred_str = json.dumps(pred)
        if '224' in pred_str:
            warnings.append("Found '224' in JSON but could not parse shape structure")
        else:
            errors.append("No shape information found in JSON. Expected shapes containing 224x224")
    else:
        valid_shapes = [s for s in shapes if check_shape_valid(s)]
        if len(valid_shapes) == 0:
            errors.append(f"No valid 224x224 shapes found. Found shapes: {shapes[:5]}")
        else:
            # Check that shapes have correct structure
            # Accept [1, 224, 224] or [1, 1, 224, 224] or similar
            for shape in valid_shapes[:5]:
                if len(shape) == 3:
                    # [C, H, W] - acceptable
                    pass
                elif len(shape) == 4:
                    # [B, C, H, W] - acceptable
                    pass
                else:
                    warnings.append(f"Unusual shape dimensionality: {shape}")

    # ---- Check 3: Label information present ----
    labels = find_labels_in_data(pred)
    if len(labels) == 0:
        warnings.append("No label information found in JSON")
    else:
        pass  # Labels found

    # ---- Check 4: Preprocessing information ----
    has_preprocessing = find_preprocessing_info(pred)
    if not has_preprocessing:
        warnings.append("No preprocessing pipeline information found in JSON")

    # ---- Check 5: TXT file has meaningful content ----
    try:
        with open(PRED_TXT, 'r') as f:
            pred_txt = f.read()

        if len(pred_txt.strip()) < 20:
            errors.append("Predicted TXT file is too short / empty")
        else:
            # Check for key information - be flexible
            has_224 = '224' in pred_txt
            has_sample_info = any(kw in pred_txt.lower() for kw in 
                                  ['sample', 'label', 'image', 'shape', 'num', 'count', 
                                   'dataset', 'preprocessing', 'step'])

            if not has_224:
                warnings.append("TXT file doesn't mention '224' (expected spatial dimension)")

            if not has_sample_info:
                errors.append("TXT file lacks meaningful dataset information")

    except Exception as e:
        errors.append(f"Error reading predicted TXT file: {e}")

    # ---- Check 6: JSON has some meaningful structure ----
    # The JSON should contain SOMETHING useful about the dataset
    pred_str = json.dumps(pred)
    meaningful_keywords = ['224', 'label', 'sample', 'train', 'val', 'shape', 
                           'preprocessing', 'class', 'num']
    found_keywords = [kw for kw in meaningful_keywords if kw in pred_str.lower()]

    if len(found_keywords) < 2:
        errors.append(f"JSON file lacks meaningful dataset content. Found keywords: {found_keywords}")

    # ---- Summary ----
    if errors:
        error_msg = "Evaluation failed: " + "; ".join(errors)
        if warnings:
            error_msg += " | Warnings: " + "; ".join(warnings)
        return (False, error_msg)

    # Build success message
    shape_info = f"shapes found: {shapes[:3]}" if shapes else "shape info in JSON"
    label_info = f"{len(set(labels))} unique labels" if labels else "label info present"
    sample_info = f"{num_samples} samples" if num_samples else "samples present"

    success_msg = (f"All checks passed: {sample_info}, {label_info}, {shape_info}. "
                   f"Output files contain proper dataset analysis.")
    if warnings:
        success_msg += f" | Warnings (non-fatal): " + "; ".join(warnings)

    return (True, success_msg)


