import os
import re
import math


def parse_dinfo_flexible(filepath):
    """
    Parse a pred_dinfo.txt file flexibly.
    Supports multiple formats:
    1. One line per frame: energy d7[0..6] d3[0..2]  (11 values per line)
    2. Labeled format with 'Total energy:', 'D (7 element vector):', 'D (3 element vector):'
    3. Any reasonable structured format with energy + 7 + 3 values
    """
    with open(filepath, 'r') as f:
        content = f.read()

    lines = [line.strip() for line in content.strip().split('\n') if line.strip()]

    # Try format 1: labeled format with section headers
    if 'Total energy:' in content or 'D (7 element vector)' in content:
        return parse_labeled_format(content)

    # Try format 2: each line has energy + 7 + 3 = 11 values
    all_numeric_lines = []
    for line in lines:
        parts = line.split()
        try:
            vals = [float(x) for x in parts]
            all_numeric_lines.append(vals)
        except ValueError:
            continue

    if all_numeric_lines:
        # Check if lines have 11 values (energy + 7 + 3)
        lines_11 = [l for l in all_numeric_lines if len(l) == 11]
        if lines_11:
            energies = [l[0] for l in lines_11]
            d7_vectors = [l[1:8] for l in lines_11]
            d3_vectors = [l[8:11] for l in lines_11]
            # Return first frame's energy for single-energy comparison, or all
            return energies, d7_vectors, d3_vectors

        # Check if lines have 10 values (7 + 3, energy separate)
        lines_10 = [l for l in all_numeric_lines if len(l) == 10]
        if lines_10:
            d7_vectors = [l[0:7] for l in lines_10]
            d3_vectors = [l[7:10] for l in lines_10]
            # Try to find energy separately
            energy_lines = [l for l in all_numeric_lines if len(l) == 1]
            if energy_lines:
                energies = [l[0] for l in energy_lines]
            else:
                energies = [0.0] * len(lines_10)
            return energies, d7_vectors, d3_vectors

        # Try: first line is energy, then alternating d7/d3 lines
        if len(all_numeric_lines) >= 3:
            if len(all_numeric_lines[0]) == 1:
                energy = all_numeric_lines[0][0]
                d7_vectors = []
                d3_vectors = []
                i = 1
                while i < len(all_numeric_lines):
                    if i < len(all_numeric_lines) and len(all_numeric_lines[i]) == 7:
                        d7_vectors.append(all_numeric_lines[i])
                        i += 1
                    if i < len(all_numeric_lines) and len(all_numeric_lines[i]) == 3:
                        d3_vectors.append(all_numeric_lines[i])
                        i += 1
                    else:
                        i += 1
                if d7_vectors and d3_vectors:
                    return [energy] * len(d7_vectors), d7_vectors, d3_vectors

    raise ValueError(f"Could not parse file {filepath} in any known format")


def parse_labeled_format(content):
    """Parse labeled format with section headers."""
    # Extract total energy
    energy_match = re.search(r'Total energy:\s*([-\d.eE+]+)', content)
    if energy_match is None:
        # Try alternative: just a float on its own line labeled differently
        energy_match = re.search(r'[Ee]nergy[:\s]+([-\d.eE+]+)', content)

    if energy_match:
        energy = float(energy_match.group(1))
    else:
        energy = 0.0

    # Extract 7-element D vectors
    d7_section = re.search(r'D \(7 element vector\):\s*\n(.*?)(?:\n\s*\n|\nD \(3 element vector\))', content, re.DOTALL)
    d7_vectors = []
    if d7_section:
        d7_lines = [line.strip() for line in d7_section.group(1).strip().split('\n') if line.strip()]
        for line in d7_lines:
            vals = [float(x) for x in line.split()]
            if len(vals) == 7:
                d7_vectors.append(vals)

    # Extract 3-element D vectors
    d3_section = re.search(r'D \(3 element vector\):\s*\n(.*)', content, re.DOTALL)
    d3_vectors = []
    if d3_section:
        d3_lines = [line.strip() for line in d3_section.group(1).strip().split('\n') if line.strip()]
        for line in d3_lines:
            vals = [float(x) for x in line.split()]
            if len(vals) == 3:
                d3_vectors.append(vals)

    energies = [energy] * max(len(d7_vectors), 1)
    return energies, d7_vectors, d3_vectors


def parse_gold_format(filepath):
    """Parse the gold file which may use labeled format."""
    with open(filepath, 'r') as f:
        content = f.read()

    lines = [line.strip() for line in content.strip().split('\n') if line.strip()]

    # Try labeled format first
    if 'Total energy:' in content:
        energies, d7_vectors, d3_vectors = parse_labeled_format(content)
        if d7_vectors and d3_vectors:
            return energies, d7_vectors, d3_vectors

    # Try numeric format
    all_numeric_lines = []
    for line in lines:
        parts = line.split()
        try:
            vals = [float(x) for x in parts]
            all_numeric_lines.append(vals)
        except ValueError:
            continue

    if all_numeric_lines:
        lines_11 = [l for l in all_numeric_lines if len(l) == 11]
        if lines_11:
            energies = [l[0] for l in lines_11]
            d7_vectors = [l[1:8] for l in lines_11]
            d3_vectors = [l[8:11] for l in lines_11]
            return energies, d7_vectors, d3_vectors

    raise ValueError(f"Could not parse gold file {filepath}")


def eval():
    pred_path = 'pred_results/pred_dinfo.txt'
    gold_path = './gold_results/pred_dinfo.txt'

    # Step 1: Check files exist
    if not os.path.exists(pred_path):
        return (False, f"Predicted output file not found: {pred_path}")
    if not os.path.exists(gold_path):
        return (False, f"Gold output file not found: {gold_path}")

    # Step 2: Parse both files
    try:
        pred_energies, pred_d7, pred_d3 = parse_dinfo_flexible(pred_path)
    except Exception as e:
        return (False, f"Failed to parse predicted output: {e}")

    try:
        gold_energies, gold_d7, gold_d3 = parse_gold_format(gold_path)
    except Exception as e:
        return (False, f"Failed to parse gold output: {e}")

    # Step 3: Basic structure checks
    if len(pred_d7) == 0:
        return (False, "No D7 vectors found in predicted output")
    if len(pred_d3) == 0:
        return (False, "No D3 vectors found in predicted output")

    # Check that D7 vectors have 7 elements
    for i, row in enumerate(pred_d7):
        if len(row) != 7:
            return (False, f"D7 vector {i} has {len(row)} elements, expected 7")

    # Check that D3 vectors have 3 elements
    for i, row in enumerate(pred_d3):
        if len(row) != 3:
            return (False, f"D3 vector {i} has {len(row)} elements, expected 3")

    # Step 4: Validate dimensions match gold
    n_frames = min(len(pred_d7), len(gold_d7))
    if n_frames == 0:
        return (False, "No matching frames between predicted and gold")

    if len(pred_d7) != len(gold_d7):
        return (False, f"Number of D7 frames mismatch: pred={len(pred_d7)}, gold={len(gold_d7)}")
    if len(pred_d3) != len(gold_d3):
        return (False, f"Number of D3 frames mismatch: pred={len(pred_d3)}, gold={len(gold_d3)}")

    # Step 5: Check for NaN/Inf in predicted values
    all_pred_vals = list(pred_energies)
    for v in pred_d7:
        all_pred_vals.extend(v)
    for v in pred_d3:
        all_pred_vals.extend(v)
    for val in all_pred_vals:
        if math.isnan(val) or math.isinf(val):
            return (False, f"Predicted output contains NaN or Inf values")

    # Step 6: Compute energy MAE
    # Use per-frame energies if available, otherwise single energy
    n_energy_frames = min(len(pred_energies), len(gold_energies))
    energy_errors = [abs(pred_energies[i] - gold_energies[i]) for i in range(n_energy_frames)]
    energy_mae = sum(energy_errors) / len(energy_errors) if energy_errors else 0.0
    # Threshold: generous 5 eV (allows for some offset)
    energy_threshold = 5.0

    # Step 7: Compute D7 MAE (average across all components and frames)
    d7_errors = []
    for pred_row, gold_row in zip(pred_d7, gold_d7):
        for pv, gv in zip(pred_row, gold_row):
            d7_errors.append(abs(pv - gv))
    d7_mae = sum(d7_errors) / len(d7_errors) if d7_errors else 0.0
    d7_threshold = 0.1  # Slightly relaxed threshold

    # Step 8: Compute D3 MAE (average across all components and frames)
    d3_errors = []
    for pred_row, gold_row in zip(pred_d3, gold_d3):
        for pv, gv in zip(pred_row, gold_row):
            d3_errors.append(abs(pv - gv))
    d3_mae = sum(d3_errors) / len(d3_errors) if d3_errors else 0.0
    d3_threshold = 0.1  # Slightly relaxed threshold

    # Step 9: Apply thresholds
    reasons = []
    passed = True

    if energy_mae > energy_threshold:
        passed = False
        reasons.append(f"Energy MAE {energy_mae:.4f} eV exceeds threshold {energy_threshold} eV")

    if d7_mae > d7_threshold:
        passed = False
        reasons.append(f"D7 vector MAE {d7_mae:.6f} exceeds threshold {d7_threshold}")

    if d3_mae > d3_threshold:
        passed = False
        reasons.append(f"D3 vector MAE {d3_mae:.6f} exceeds threshold {d3_threshold}")

    if passed:
        return (True, f"All checks passed. Energy MAE: {energy_mae:.4f}, D7 MAE: {d7_mae:.6f}, D3 MAE: {d3_mae:.6f}")
    else:
        return (False, "; ".join(reasons))


if __name__ == '__main__':
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

import os
import csv
import math


def eval():
    pred_dir = "pred_results"
    gold_dir = "./gold_results/"

    # 1. Check all three files exist
    required_files = ["pred_plevdw.png", "pred_plevdw.csv", "pred_plevdw_params.txt"]
    for f in required_files:
        pred_path = os.path.join(pred_dir, f)
        if not os.path.exists(pred_path):
            return (False, f"Missing required output file: {f}")

    # 2. Validate PNG is a valid image with non-trivial size
    png_path = os.path.join(pred_dir, "pred_plevdw.png")
    png_size = os.path.getsize(png_path)
    if png_size < 1024:
        return (False, f"PNG file too small ({png_size} bytes), likely invalid")
    with open(png_path, "rb") as f:
        header = f.read(8)
    if header[:4] != b'\x89PNG':
        return (False, "pred_plevdw.png is not a valid PNG file")

    # 3. Parse parameters - check that key parameters are present and physically reasonable
    pred_params_path = os.path.join(pred_dir, "pred_plevdw_params.txt")

    def parse_params(filepath):
        params = {}
        with open(filepath, "r") as f:
            for line in f:
                line = line.strip()
                if ":" in line:
                    parts = line.split(":", 1)
                    key = parts[0].strip().lower()
                    try:
                        val = float(parts[1].strip())
                        params[key] = val
                    except ValueError:
                        pass
        return params

    pred_params = parse_params(pred_params_path)

    def has_param_matching(params, patterns):
        """Check if any key in params matches any of the given patterns (case-insensitive substring match)."""
        for key in params:
            for pattern in patterns:
                if pattern.lower() in key.lower():
                    return True
        return False

    def get_param_matching(params, patterns):
        """Get value of first key matching any pattern."""
        for key in params:
            for pattern in patterns:
                if pattern.lower() in key.lower():
                    return params[key]
        return None

    # Check required parameters are present - use flexible matching
    # gamma can appear as 'gamma_c', 'gamma_o', 'gamma', etc.
    # gammaw can appear as 'gammaw_c', 'gammaw_o', 'gammaw', etc.
    required_param_patterns = [
        (["devdw"], "Devdw (well depth)"),
        (["gamma"], "gamma parameter"),
        (["gammaw"], "gammaw parameter"),
        (["alfa"], "alfa parameter"),
        (["vdw1"], "vdw1 parameter"),
        (["rvdw"], "rvdw parameter"),
    ]

    missing_params = []
    for patterns, description in required_param_patterns:
        if not has_param_matching(pred_params, patterns):
            missing_params.append(description)

    if missing_params:
        return (False, f"Missing parameter(s) in pred_plevdw_params.txt: {missing_params}")

    # Check parameters are physically reasonable (not NaN or Inf)
    for key, val in pred_params.items():
        if math.isnan(val) or math.isinf(val):
            return (False, f"Parameter '{key}' has non-finite value: {val}")

    # Try to load gold params if available
    gold_params_path = os.path.join(gold_dir, "pred_plevdw_params.txt")
    gold_params = {}
    if os.path.exists(gold_params_path):
        gold_params = parse_params(gold_params_path)

        # Only check parameters that are unambiguous (pair-specific, not atom-specific)
        # devdw, alfa, rvdw are pair parameters - should match exactly
        # vdw1 is a global parameter - should match exactly
        unambiguous_checks = [
            (["devdw"], "devdw"),
            (["alfa"], "alfa"),
            (["rvdw"], "rvdw"),
            (["vdw1"], "vdw1"),
        ]
        for patterns, name in unambiguous_checks:
            pred_val = get_param_matching(pred_params, patterns)
            gold_val = get_param_matching(gold_params, patterns)
            if pred_val is not None and gold_val is not None:
                if abs(pred_val - gold_val) > 0.05:
                    return (False, f"Unambiguous parameter '{name}' mismatch: "
                                   f"pred={pred_val}, gold={gold_val}")

    # 4. Load and validate CSV data
    pred_csv_path = os.path.join(pred_dir, "pred_plevdw.csv")

    def load_csv(filepath):
        distances = []
        energies = []
        with open(filepath, "r") as f:
            reader = csv.reader(f)
            header = next(reader)  # skip header
            for row in reader:
                if len(row) >= 2:
                    try:
                        d = float(row[0])
                        e = float(row[1])
                        distances.append(d)
                        energies.append(e)
                    except ValueError:
                        pass
        return distances, energies

    pred_distances, pred_energies = load_csv(pred_csv_path)

    # Check minimum data points
    if len(pred_distances) < 20:
        return (False, f"Too few data points in CSV: {len(pred_distances)} (need at least 20)")

    # Check distance range covers ~2.0 to ~3.0
    if min(pred_distances) > 2.05:
        return (False, f"Distance range starts too high: {min(pred_distances):.4f} (should start near 2.0)")
    if max(pred_distances) < 2.95:
        return (False, f"Distance range ends too low: {max(pred_distances):.4f} (should end near 3.0)")

    # Check all values are finite
    for i, (d, e) in enumerate(zip(pred_distances, pred_energies)):
        if math.isnan(d) or math.isinf(d) or math.isnan(e) or math.isinf(e):
            return (False, f"Non-finite value at row {i}: distance={d}, energy={e}")

    # Check monotonically increasing distances
    for i in range(1, len(pred_distances)):
        if pred_distances[i] <= pred_distances[i - 1]:
            return (False, f"Distances not monotonically increasing at row {i}")

    # 5. Compare energy values against gold standard if available
    gold_csv_path = os.path.join(gold_dir, "pred_plevdw.csv")

    max_rel_error = 0.0
    max_abs_error = 0.0
    energy_comparison_done = False

    if os.path.exists(gold_csv_path):
        gold_distances, gold_energies = load_csv(gold_csv_path)

        if len(gold_distances) > 0:
            energy_comparison_done = True
            for gd, ge in zip(gold_distances, gold_energies):
                # Find closest pred distance
                best_idx = None
                best_dist_diff = float("inf")
                for i, pd_val in enumerate(pred_distances):
                    diff = abs(pd_val - gd)
                    if diff < best_dist_diff:
                        best_dist_diff = diff
                        best_idx = i

                if best_dist_diff > 0.05:
                    continue

                pe = pred_energies[best_idx]
                abs_error = abs(pe - ge)
                max_abs_error = max(max_abs_error, abs_error)
                if abs(ge) > 0.01:
                    rel_error = abs_error / abs(ge)
                    max_rel_error = max(max_rel_error, rel_error)

            # Use lenient tolerances since there's ambiguity in gamma/gammaw choice
            if max_rel_error > 0.30:
                return (False, f"Energy values differ too much from gold standard: "
                               f"max relative error = {max_rel_error:.4f} (threshold: 0.30)")
            if max_abs_error > 20.0:
                return (False, f"Energy values differ too much from gold standard: "
                               f"max absolute error = {max_abs_error:.4f} kcal/mol (threshold: 20.0)")

    # 6. Validate physical behavior: energy should generally decrease over the 2.0-3.0 range
    # (we're on the repulsive wall side, so energy decreases with distance)
    if pred_energies[0] < pred_energies[-1]:
        return (False, "Energy profile has unexpected shape: energy increases with distance in 2.0-3.0 range")

    # 7. Check that energies are in a reasonable range for van der Waals interactions
    energy_range = max(pred_energies) - min(pred_energies)
    if energy_range < 0.01:
        return (False, f"Energy range too small ({energy_range:.4f} kcal/mol), profile appears flat")

    msg = f"All checks passed. {len(pred_distances)} data points, all required parameters present"
    if energy_comparison_done:
        msg += f", max relative error = {max_rel_error:.4f}, max absolute error = {max_abs_error:.4f}"

    return (True, msg)


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

import os
import numpy as np
from PIL import Image


def eval():
    pred_path = "pred_results/pred_plot_every_class.png"

    # 1. Check predicted file exists
    if not os.path.exists(pred_path):
        return (False, "Predicted plot file not found at pred_results/pred_plot_every_class.png")

    # 2. Validate predicted file is a valid image with non-zero size
    pred_size = os.path.getsize(pred_path)
    if pred_size == 0:
        return (False, "Predicted plot file is empty (0 bytes)")

    try:
        pred_img = Image.open(pred_path)
        pred_img.verify()
    except Exception as e:
        return (False, f"Predicted plot is not a valid image: {e}")

    # Re-open after verify (verify closes the file)
    pred_img = Image.open(pred_path)
    pred_w, pred_h = pred_img.size

    # 3. Check image dimensions are reasonable
    if pred_w < 100 or pred_h < 100:
        return (False, f"Predicted plot dimensions too small: {pred_w}x{pred_h}")

    # 4. Check image is not mostly blank
    pred_arr = np.array(pred_img.convert("RGB"), dtype=np.float64)
    pred_gray = np.mean(pred_arr, axis=2)
    non_white_fraction = np.mean(pred_gray < 240)
    if non_white_fraction < 0.03:
        return (False, f"Plot appears mostly blank ({non_white_fraction:.1%} non-white pixels)")

    # 5. Validate the underlying computation using the confusion matrix data
    # Try multiple possible file paths for the confusion matrix
    possible_paths = [
        'benchmark/datasets/Automatic-Modulation-Classification/Part4_CNN based AMC/Some Result/train num/train num 100000x4/pred_confusion_mat_L100.npy',
        'benchmark/datasets/Automatic-Modulation-Classification/Part6_CNN with Transfer Learning on AMC/pred_confusion_mat_L100.npy',
    ]

    confusion_matrices = None
    for path in possible_paths:
        if os.path.exists(path):
            try:
                confusion_matrices = np.load(path)
                break
            except Exception:
                continue

    if confusion_matrices is None:
        # Can't validate computation, but file exists and looks valid
        # Check basic image properties as a fallback
        # Check image has multiple distinct colors (suggesting multiple plotted lines)
        pred_img_rgb = pred_img.convert("RGB")
        pred_rgb_arr = np.array(pred_img_rgb)

        # Sample unique colors in the image
        reshaped = pred_rgb_arr.reshape(-1, 3)
        # Check there's enough color variation to suggest multiple lines
        color_std = np.std(reshaped.astype(float), axis=0)
        if np.mean(color_std) < 5:
            return (False, "Plot appears to lack color variation (expected multiple colored lines)")

        return (True, f"Plot file exists, is valid, and appears to contain content (gold data unavailable for detailed validation)")

    # 6. Validate computed accuracies
    snr_levels = np.arange(-10, 21, 2)
    num_classes = 4
    num_snr = len(snr_levels)

    # Check confusion matrix shape
    expected_shape_per_snr = (num_classes, num_classes)

    if confusion_matrices.ndim == 3:
        if confusion_matrices.shape[0] != num_snr:
            return (False, f"Confusion matrix has unexpected number of SNR levels: {confusion_matrices.shape[0]}, expected {num_snr}")
        if confusion_matrices.shape[1:] != expected_shape_per_snr:
            return (False, f"Confusion matrix per-SNR shape is {confusion_matrices.shape[1:]}, expected {expected_shape_per_snr}")
    else:
        return (False, f"Confusion matrix has unexpected dimensions: {confusion_matrices.ndim}")

    # Compute expected accuracies
    expected_accuracies = np.zeros((num_classes, num_snr))
    for snr_idx in range(num_snr):
        cm = confusion_matrices[snr_idx]
        for class_idx in range(num_classes):
            true_pos = cm[class_idx, class_idx]
            total = np.sum(cm[class_idx, :])
            if total > 0:
                expected_accuracies[class_idx, snr_idx] = true_pos / total

    # Validate accuracy values are in valid range [0, 1]
    if np.any(expected_accuracies < 0) or np.any(expected_accuracies > 1):
        return (False, "Computed accuracies are out of valid range [0, 1]")

    # Check that the plot has appropriate non-white content consistent with having curves
    # A plot with 4 curves over 16 SNR points should have meaningful non-white content
    if non_white_fraction < 0.05:
        return (False, f"Plot appears too sparse for a 4-class accuracy plot ({non_white_fraction:.1%} non-white pixels)")

    # 7. Check image has multiple colors suggesting multiple plotted lines
    pred_img_rgb = pred_img.convert("RGB")
    pred_rgb_arr = np.array(pred_img_rgb)

    # Check color diversity in the image (multiple lines = multiple colors)
    # Sample pixels that are not near-white (background)
    non_white_mask = np.mean(pred_rgb_arr, axis=2) < 230
    if np.sum(non_white_mask) > 100:
        colored_pixels = pred_rgb_arr[non_white_mask]
        # Check that there are multiple distinct hues
        r_range = np.max(colored_pixels[:, 0]) - np.min(colored_pixels[:, 0])
        g_range = np.max(colored_pixels[:, 1]) - np.min(colored_pixels[:, 1])
        b_range = np.max(colored_pixels[:, 2]) - np.min(colored_pixels[:, 2])
        color_diversity = r_range + g_range + b_range
        if color_diversity < 100:
            return (False, f"Plot appears to lack color diversity (expected 4 different colored lines), color_diversity={color_diversity}")

    # 8. Verify the plot covers the expected SNR range by checking image width is reasonable
    # (indirect check - if the image is valid and has content, it likely has the right range)

    # Summary validation
    avg_high_snr_acc = np.mean(expected_accuracies[:, -3:])  # Average accuracy at high SNR
    avg_low_snr_acc = np.mean(expected_accuracies[:, :3])    # Average accuracy at low SNR

    # At high SNR, we generally expect better performance than low SNR
    # This is a sanity check on the data
    if avg_high_snr_acc < avg_low_snr_acc and avg_high_snr_acc < 0.3:
        return (False, f"Accuracy data seems suspicious: high SNR avg ({avg_high_snr_acc:.3f}) < low SNR avg ({avg_low_snr_acc:.3f})")

    return (True, f"Plot is valid and computation is correct. High SNR avg accuracy: {avg_high_snr_acc:.3f}, Low SNR avg accuracy: {avg_low_snr_acc:.3f}")


