        return (False, f"Missing predicted PNG file: {pred_png}")

    # 2. Validate PNG file (check magic bytes)
    with open(pred_png, "rb") as f:
        header = f.read(8)
    if header[:4] != b"\x89PNG":
        return (False, "Predicted PNG file is not a valid PNG image")

    # 3. Load predicted text data - handle both (16,2) and (2,16) formats
    try:
        pred_data = np.loadtxt(pred_txt)
    except Exception as e:
        return (False, f"Failed to parse predicted text file: {e}")

    # 4. Handle different possible shapes
    # Could be (16, 2) with rows=[snr, acc] or (2, 16) with cols=[snr, acc]
    if pred_data.shape == (16, 2):
        pred_snr = pred_data[:, 0]
        pred_acc = pred_data[:, 1]
    elif pred_data.shape == (2, 16):
        pred_snr = pred_data[0]
        pred_acc = pred_data[1]
    else:
        return (False, f"Predicted text data has unexpected shape {pred_data.shape}, expected (16, 2) or (2, 16)")

    # 5. Verify SNR values match expected range: -10 to 20 in steps of 2
    expected_snr = np.arange(-10, 21, 2, dtype=float)
    if len(pred_snr) != 16:
        return (False, f"Expected 16 SNR values, got {len(pred_snr)}")

    if not np.allclose(pred_snr, expected_snr, atol=0.1):
        return (False, f"SNR values do not match expected range -10 to 20 dB in 2 dB steps. Got: {pred_snr}")

    # 6. All 16 data points must be present
    if len(pred_acc) != 16:
        return (False, f"Expected 16 accuracy values, got {len(pred_acc)}")

    # 7. Accuracy values should be in [0, 1]
    if np.any(pred_acc < 0) or np.any(pred_acc > 1):
        return (False, f"Accuracy values out of [0,1] range: min={pred_acc.min()}, max={pred_acc.max()}")

    # 8. Verify accuracy is computed from the actual confusion matrices
    try:
        file_path = 'benchmark/datasets/Automatic-Modulation-Classification/Part6_CNN with Transfer Learning on AMC/2_finetune_conv1+conv2+nn/100/pred_confusion_mat_L100.npy'
        confusion_matrices = np.load(file_path)

        expected_accuracies = []
        for matrix in confusion_matrices:
            correct = np.trace(matrix)
            total_samples = np.sum(matrix)
            accuracy = correct / total_samples
            expected_accuracies.append(accuracy)
        expected_accuracies = np.array(expected_accuracies)

        if len(expected_accuracies) != 16:
            return (False, f"Confusion matrices contain {len(expected_accuracies)} entries, expected 16")

        tolerance = 0.001
        if not np.allclose(pred_acc, expected_accuracies, atol=tolerance):
            max_diff = np.max(np.abs(pred_acc - expected_accuracies))
            mismatches = np.where(np.abs(pred_acc - expected_accuracies) > tolerance)[0]
            return (False, f"Accuracy values differ from expected computation. Max difference: {max_diff:.6f}. "
                           f"Mismatches at SNR indices: {mismatches.tolist()}")
    except Exception as e:
        # If we can't load the reference data, do basic sanity checks only
        print(f"Warning: Could not load reference confusion matrices: {e}")

        # 9. Check general increasing trend (allow minor fluctuations <= 5%)
        for i in range(1, len(pred_acc)):
            if pred_acc[i] < pred_acc[i - 1] - 0.05:
                return (False, f"Accuracy drops by more than 5% from SNR index {i-1} to {i}: "
                               f"{pred_acc[i-1]:.4f} -> {pred_acc[i]:.4f}")

        # 10. Final accuracy at 20 dB should be >= 0.70
        if pred_acc[-1] < 0.70:
            return (False, f"Accuracy at 20 dB SNR is {pred_acc[-1]:.4f}, expected >= 0.70")

    # 11. Check general increasing trend (allow minor fluctuations <= 5%)
    for i in range(1, len(pred_acc)):
        if pred_acc[i] < pred_acc[i - 1] - 0.05:
            return (False, f"Accuracy drops by more than 5% from SNR index {i-1} to {i}: "
                           f"{pred_acc[i-1]:.4f} -> {pred_acc[i]:.4f}")

    # 12. Final accuracy at 20 dB should be >= 0.70
    if pred_acc[-1] < 0.70:
        return (False, f"Accuracy at 20 dB SNR is {pred_acc[-1]:.4f}, expected >= 0.70")

    return (True, "All checks passed: 16 SNR points present, accuracies correctly computed from confusion matrices, "
                  "PNG plot generated, increasing trend confirmed.")


